## Layer-by-Layer Implementation Guide

### 1. API Layer (`api/`)

**CRITICAL RULE**: ALL API requests MUST be defined in the `api/` folder

#### Axios Client Setup

```typescript
// api/client/axios-client.ts
import axios, { AxiosInstance } from 'axios';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000/api';

export const apiClient: AxiosInstance = axios.create({
  baseURL: API_BASE_URL,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});

export default apiClient;
```

#### Interceptors

```typescript
// api/client/interceptors.ts
import { apiClient } from './axios-client';
import { getToken, clearAuth } from '@/utils/storage';

// Request interceptor - Add auth token
apiClient.interceptors.request.use(
  (config) => {
    const token = getToken();
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor - Handle errors
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      // Unauthorized - clear auth and redirect
      clearAuth();
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);
```

#### API Endpoint Functions

```typescript
// api/endpoints/auth.api.ts
import { apiClient } from '../client/axios-client';
import type { 
  LoginRequest, 
  LoginResponse, 
  RegisterRequest, 
  RegisterResponse 
} from '@/types/auth';

export const authApi = {
  login: async (data: LoginRequest): Promise<LoginResponse> => {
    const response = await apiClient.post<LoginResponse>('/auth/login', data);
    return response.data;
  },

  register: async (data: RegisterRequest): Promise<RegisterResponse> => {
    const response = await apiClient.post<RegisterResponse>('/auth/register', data);
    return response.data;
  },

  logout: async (): Promise<void> => {
    await apiClient.post('/auth/logout');
  },

  getCurrentUser: async () => {
    const response = await apiClient.get('/auth/me');
    return response.data;
  },
};

// api/endpoints/user.api.ts
import { apiClient } from '../client/axios-client';
import type { User, UpdateUserRequest } from '@/types/user';

export const userApi = {
  getUsers: async () => {
    const response = await apiClient.get<User[]>('/users');
    return response.data;
  },

  getUserById: async (id: string) => {
    const response = await apiClient.get<User>(`/users/${id}`);
    return response.data;
  },

  updateUser: async (id: string, data: UpdateUserRequest) => {
    const response = await apiClient.put<User>(`/users/${id}`, data);
    return response.data;
  },

  deleteUser: async (id: string) => {
    await apiClient.delete(`/users/${id}`);
  },
};

// api/index.ts
export * from './endpoints/auth.api';
export * from './endpoints/user.api';
```

