                                for (const copy of copies) {
                                  rowsWithToggles.push({ type: "quote", row: copy, isChild: true });
                                }
                              }
                            }
                          }

                          const orphanCopyRows = copyRows.filter(
                            (copy) => !mainRows.some((main) => main.transactionId === copy.transactionId),
