                                        onClick={() =>
                                          setExpandedCopyGroups((prev) => ({
                                            ...prev,
                                            [item.parentId]: !prev[item.parentId],
                                          }))
                                        }
                                      >
                                        <ChevronDown className={`h-3.5 w-3.5 transition ${isExpanded ? "rotate-180" : ""}`} />
                                        {isExpanded ? "Hide" : "Show"} {item.count} {item.count === 1 ? "copy" : "copies"}
                                      </button>
                                    );
                                  }

