                  <h1 className="text-xl font-semibold text-black/90" data-testid="text-ticket-subject">
                    {ticket.subject}
                  </h1>
                  {ticket.description && (
                    <p className="text-black/60 mt-2" data-testid="text-ticket-description">
                      {ticket.description}
                    </p>
