              size="sm"
              variant="outline"
              className="mt-4"
              onClick={() => setLocation("/clients")}
            >
              Back to Clients
            </Button>
          </div>
        </div>
      </CommandCenterShell>
    );
  }

  return (
    <CommandCenterShell role={role} title={pageLabel} theme="light" onRoleChange={() => {}} filterSlot={<></>}>
      <div className="px-5 pb-8 pt-5" data-testid="page-quote">
