@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --color-background: hsl(var(--background));
  --color-foreground: hsl(var(--foreground));

  --color-card: hsl(var(--card));
  --color-card-foreground: hsl(var(--card-foreground));

  --color-popover: hsl(var(--popover));
  --color-popover-foreground: hsl(var(--popover-foreground));

  --color-primary: hsl(var(--primary));
  --color-primary-foreground: hsl(var(--primary-foreground));

  --color-secondary: hsl(var(--secondary));
  --color-secondary-foreground: hsl(var(--secondary-foreground));

  --color-muted: hsl(var(--muted));
  --color-muted-foreground: hsl(var(--muted-foreground));

  --color-accent: hsl(var(--accent));
  --color-accent-foreground: hsl(var(--accent-foreground));

  --color-destructive: hsl(var(--destructive));
  --color-destructive-foreground: hsl(var(--destructive-foreground));

  --color-border: hsl(var(--border));
  --color-input: hsl(var(--input));
  --color-ring: hsl(var(--ring));

  --color-sidebar: hsl(var(--sidebar));
  --color-sidebar-foreground: hsl(var(--sidebar-foreground));
  --color-sidebar-primary: hsl(var(--sidebar-primary));
  --color-sidebar-primary-foreground: hsl(var(--sidebar-primary-foreground));
  --color-sidebar-accent: hsl(var(--sidebar-accent));
  --color-sidebar-accent-foreground: hsl(var(--sidebar-accent-foreground));
  --color-sidebar-border: hsl(var(--sidebar-border));
  --color-sidebar-ring: hsl(var(--sidebar-ring));

  --font-sans: "DM Sans", ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto,
    Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  --font-serif: "Fraunces", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: "Fira Code", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas,
    "Liberation Mono", "Courier New", monospace;

  --tracking-normal: 0em;
  --spacing: 0.25rem;
}

:root {
  --background: 0 0% 99%;
  --foreground: 240 10% 8%;

  --card: 0 0% 100%;
  --card-foreground: 240 10% 8%;

  --popover: 0 0% 100%;
  --popover-foreground: 240 10% 8%;

  --primary: 217 91% 60%;
  --primary-foreground: 0 0% 100%;

  --secondary: 240 10% 96%;
  --secondary-foreground: 240 10% 10%;

  --muted: 240 8% 96%;
  --muted-foreground: 240 5% 45%;

  --accent: 155 70% 36%;
  --accent-foreground: 0 0% 100%;

  --destructive: 0 84% 55%;
  --destructive-foreground: 0 0% 100%;

  --border: 240 12% 90%;
  --input: 240 12% 88%;
  --ring: 217 91% 60%;

  --sidebar: 0 0% 99%;
  --sidebar-foreground: 240 10% 10%;
  --sidebar-border: 240 12% 88%;
  --sidebar-primary: 217 91% 60%;
  --sidebar-primary-foreground: 0 0% 100%;
  --sidebar-accent: 240 10% 96%;
  --sidebar-accent-foreground: 240 10% 10%;
  --sidebar-ring: 217 91% 60%;

  --radius: 1rem;
}

.dark {
  --background: 0 0% 0%;
  --foreground: 210 20% 96%;

  --card: 240 10% 6.5%;
  --card-foreground: 210 20% 96%;

  --popover: 240 10% 6.5%;
  --popover-foreground: 210 20% 96%;

  --primary: 217 91% 60%;
  --primary-foreground: 0 0% 100%;

  --secondary: 240 9% 12%;
  --secondary-foreground: 210 20% 96%;

  --muted: 240 8% 10%;
  --muted-foreground: 220 10% 68%;

  --accent: 155 86% 57%;
  --accent-foreground: 240 10% 6%;

  --destructive: 0 84% 60%;
  --destructive-foreground: 210 20% 96%;

  --border: 240 8% 16%;
  --input: 240 8% 20%;
  --ring: 217 91% 60%;
}

@layer base {
  * {
    @apply border-border;
  }

  html {
    color-scheme: light dark;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
    background-image:
      radial-gradient(1200px 800px at 18% 10%, hsl(204 100% 52% / 0.10), transparent 60%),
      radial-gradient(900px 700px at 80% 18%, hsl(155 70% 42% / 0.08), transparent 60%),
      radial-gradient(900px 560px at 50% 110%, hsl(270 90% 65% / 0.06), transparent 55%);
  }

  .dark body {
    background-image: none;
  }
}

@layer utilities {
  .app-shell {
    min-height: 100vh;
    background: hsl(var(--background));
  }

  .glass {
    background: linear-gradient(
      180deg,
      hsl(0 0% 100% / 0.60),
      hsl(240 10% 98% / 0.52)
    );
    border: 1px solid hsl(240 12% 86% / 0.8);
    box-shadow:
      0 30px 80px hsl(240 30% 2% / 0.08),
      0 1px 0 hsl(0 0% 100% / 0.45) inset;
    backdrop-filter: blur(16px);
  }

  .dark .glass {
    background: linear-gradient(
      180deg,
      hsl(240 10% 8% / 0.58),
      hsl(240 10% 6% / 0.50)
    );
    border: 1px solid hsl(240 8% 18% / 0.7);
    box-shadow:
      0 30px 80px hsl(240 30% 2% / 0.45),
      0 1px 0 hsl(0 0% 100% / 0.04) inset;
  }

  .grain {
    position: relative;
    isolation: isolate;
  }

  .grain::before {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: -1;
    opacity: 0.10;
