                ) : (
                  nav.items.map((item) => {
                    const isActive = active === item.key;
                    const hasChildren = item.children && item.children.length > 0;
                    const childActive = hasChildren && item.children!.some((c) => active === c.key);
                    return (
                      <div key={item.key}>
