                { key: "cottages-admin", label: "Cottages", icon: <Building2 className="h-4 w-4" /> },
                { key: "lodges-admin", label: "Lodges", icon: <Building2 className="h-4 w-4" /> },
                { key: "cruise-extras", label: "Cruise Extras", icon: <LifeBuoy className="h-4 w-4" /> },
