        </div>

        <Separator className="my-4 bg-black/10 dark:bg-white/10" />

        <nav className="space-y-1">
          {nav.grouped ? (
            nav.sections.map((section) => {
              const isExpanded = expandedSections.includes(section.id);
              return (
