  const title = useMemo(() => {
    const map: Record<string, string> = {
      overview: "Overview",
      clients: "Clients",
      enquiries: "Enquiries",
      quotes: "Quotes",
      bookings: "Bookings",
      org: "Organisation",
      users: "Users & Roles",
      audit: "Audit",
      settings: "Settings",
      "tour-operators": "Tour Operators",
      airports: "Airports",
      "agent-settings": "Settings",
      team: "Team Pipeline",
