import { useState, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Pin, Reply, Pencil, Trash2, MessageSquare } from "lucide-react";
import { useUpdateNote, useDeleteNote, useCreateNote } from "@/hooks/mutations";
import { useToast } from "@/hooks/use-toast";
import { useFavorites } from "@/hooks/queries/use-favorite-queries";
import { useToggleFavorite } from "@/hooks/mutations/use-favorite-mutations";
import type { TransactionNote } from "@/types/quote";
import type { Favorite } from "@/api/endpoints/favorite.api";
import { formatRelativeTime } from "../utils/formatters";
import { NoteEditor } from "./NoteEditor";
import { ReplyCard } from "./ReplyCard";

interface NoteCardProps {
  note: TransactionNote;
  replies: TransactionNote[];
  quoteId: string;
  currentUserName: string;
}

export function NoteCard({ note, replies, quoteId, currentUserName }: NoteCardProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [isReplying, setIsReplying] = useState(false);
  const [showReplies, setShowReplies] = useState(true);
  const { toast } = useToast();
  const updateMutation = useUpdateNote(quoteId);
  const deleteMutation = useDeleteNote(quoteId);
  const createMutation = useCreateNote(quoteId);
  const { data: userFavorites } = useFavorites();
  const toggleFavoriteMutation = useToggleFavorite();

  const isNotePinned = useMemo(() => {
    if (!userFavorites) return false;
    return userFavorites.some((f: Favorite) => f.itemType === "note" && f.itemId === note.id);
  }, [userFavorites, note.id]);

  const handleEdit = (html: string) => {
    updateMutation.mutate(
      { id: note.id, content: html },
      {
        onSuccess: () => { 
          setIsEditing(false); 
          toast({ title: "Note updated" }); 
        },
        onError: () => toast({ title: "Failed to update note", variant: "destructive" }),
      }
    );
  };

  const handleDelete = () => {
    deleteMutation.mutate(note.id, {
      onSuccess: () => toast({ title: "Note deleted" }),
      onError: () => toast({ title: "Failed to delete note", variant: "destructive" }),
    });
  };

  const handleReply = (html: string) => {
    createMutation.mutate(
      { transaction_id: quoteId, content: html },
      {
        onSuccess: () => { 
          setIsReplying(false); 
          toast({ title: "Reply added" }); 
        },
        onError: () => toast({ title: "Failed to add reply", variant: "destructive" }),
      }
    );
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -8 }}
      transition={{ duration: 0.2 }}
      className="group"
      data-testid={`note-card-${note.id}`}
    >
      <div className="rounded-xl border border-black/10 bg-white/60 p-2">
        <div className="flex items-start justify-between gap-1.5">
          <div className="flex items-center gap-1.5">
            <div className="flex h-5 w-5 items-center justify-center rounded-full bg-[#3b82f6]/10 text-[8px] font-bold text-[#3b82f6]" data-testid={`note-avatar-${note.id}`}>
              {(note.agent_id || "A").charAt(0).toUpperCase()}
            </div>
            <div>
              <span className="text-[11px] font-semibold text-black/80" data-testid={`note-author-${note.id}`}>
                {note.agent_id || "Agent"}
              </span>
              <span className="ml-1.5 text-[9px] text-black/40" data-testid={`note-time-${note.id}`}>
                {formatRelativeTime(note.createdAt)}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-0.5 opacity-0 transition group-hover:opacity-100">
            <button
              type="button"
              onClick={() => toggleFavoriteMutation.mutate(
                { 
                  itemType: "note", 
                  itemId: note.id, 
                  label: `Note by ${note.agent_id || "Agent"}`, 
                  subtitle: `quoteId:${quoteId}|${(note.content || "").replace(/<[^>]*>/g, "").slice(0, 40)}` 
                },
                { 
                  onSuccess: (data: { favorited?: boolean }) => { 
                    toast({ title: data?.favorited ? "Pinned to dashboard" : "Unpinned from dashboard" }); 
                  } 
                }
              )}
              className={`inline-flex h-5 w-5 items-center justify-center rounded transition ${isNotePinned ? "text-amber-600 hover:bg-amber-50" : "text-black/40 hover:bg-black/5 hover:text-black/70"}`}
              title={isNotePinned ? "Unpin" : "Pin to dashboard"}
              data-testid={`note-btn-pin-${note.id}`}
            >
              <Pin className="h-2.5 w-2.5" />
            </button>
            <button 
              type="button" 
              onClick={() => setIsReplying(!isReplying)} 
              className="inline-flex h-5 w-5 items-center justify-center rounded text-black/40 transition hover:bg-black/5 hover:text-black/70" 
              title="Reply" 
              data-testid={`note-btn-reply-${note.id}`}
            >
              <Reply className="h-2.5 w-2.5" />
            </button>
            <button 
              type="button" 
              onClick={() => setIsEditing(!isEditing)} 
              className="inline-flex h-5 w-5 items-center justify-center rounded text-black/40 transition hover:bg-black/5 hover:text-black/70" 
              title="Edit" 
              data-testid={`note-btn-edit-${note.id}`}
            >
              <Pencil className="h-2.5 w-2.5" />
            </button>
            <button 
              type="button" 
              onClick={handleDelete} 
              className="inline-flex h-5 w-5 items-center justify-center rounded text-black/40 transition hover:bg-rose-50 hover:text-rose-500" 
              title="Delete" 
              data-testid={`note-btn-delete-${note.id}`}
            >
              <Trash2 className="h-2.5 w-2.5" />
            </button>
          </div>
        </div>

        {isEditing ? (
          <div className="mt-1.5">
            <NoteEditor
              initialContent={note.content ?? undefined}
              onSubmit={handleEdit}
              onCancel={() => setIsEditing(false)}
              submitLabel="Save"
              isLoading={updateMutation.isPending}
              compact
            />
          </div>
        ) : (
          <div
            className="mt-1 prose prose-sm max-w-none text-[11px] leading-relaxed text-black/70 [&_a]:text-[#3b82f6] [&_ul]:pl-3 [&_ol]:pl-3"
            dangerouslySetInnerHTML={{ __html: note.content || "" }}
            data-testid={`note-content-${note.id}`}
          />
        )}

        {replies.length > 0 && (
          <div className="mt-1.5">
            <button
              type="button"
              onClick={() => setShowReplies(!showReplies)}
              className="inline-flex items-center gap-1 text-[9px] font-semibold text-[#3b82f6] transition hover:text-[#3b82f6]/80"
              data-testid={`note-toggle-replies-${note.id}`}
            >
              <MessageSquare className="h-2.5 w-2.5" />
              {showReplies ? "Hide" : "Show"} {replies.length} {replies.length === 1 ? "reply" : "replies"}
            </button>

            <AnimatePresence>
              {showReplies && (
                <motion.div
                  initial={{ height: 0, opacity: 0 }}
                  animate={{ height: "auto", opacity: 1 }}
                  exit={{ height: 0, opacity: 0 }}
                  transition={{ duration: 0.2 }}
                  className="mt-1.5 space-y-1 overflow-hidden border-l-2 border-[#3b82f6]/20 pl-2"
                >
                  {replies.map((reply) => (
                    <ReplyCard key={reply.id} reply={reply} quoteId={quoteId} />
                  ))}
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        )}

        {isReplying && (
          <div className="mt-1.5">
            <NoteEditor
              placeholder="Write a reply..."
              onSubmit={handleReply}
              onCancel={() => setIsReplying(false)}
              submitLabel="Reply"
              isLoading={createMutation.isPending}
              compact
            />
          </div>
        )}
      </div>
    </motion.div>
  );
}

client/src/pages/hub/hub-profiles.tsx.content:
import { motion } from "framer-motion";
import {
  Award,
  BookOpen,
  FileText,
  Heart,
  MapPin,
  Pen,
  Pin,
  Plus,
  Star,
  Trophy,
  Upload,
  Video,
} from "lucide-react";
import { HubSectionHeader, HubAvatar, HubBadge, HubProgressBar } from "@/components/hub-components";
import { agentProfiles } from "@/data/hub-mock";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

function SkillHeatmap({ skills }: { skills: { name: string; level: number }[] }) {
  const getColor = (level: number) => {
    if (level >= 90) return "bg-emerald-500";
    if (level >= 75) return "bg-blue-500";
    if (level >= 50) return "bg-amber-500";
    return "bg-slate-400";
  };

  return (
    <div className="space-y-2">
      {skills.map((skill) => (
        <div key={skill.name} className="flex items-center gap-3">
          <span className="w-24 text-xs text-slate-600 dark:text-slate-400">{skill.name}</span>
          <div className="flex-1">
            <div className="h-3 w-full rounded-full bg-slate-200 dark:bg-slate-700">
              <motion.div
                initial={{ width: 0 }}
                animate={{ width: `${skill.level}%` }}
                transition={{ duration: 0.8, ease: "easeOut" }}
                className={cn("h-3 rounded-full", getColor(skill.level))}
              />
            </div>
          </div>
          <span className="w-8 text-right text-xs font-medium text-slate-500">{skill.level}</span>
        </div>
      ))}
    </div>
  );
}

function StatCard({ icon: Icon, label, value, color }: { icon: React.ElementType; label: string; value: string | number; color: string }) {
  return (
    <div className="rounded-xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-900">
      <div className={cn("grid h-10 w-10 place-items-center rounded-lg", color)}>
        <Icon className="h-5 w-5 text-white" />
      </div>
      <p className="mt-2 text-2xl font-bold text-slate-900 dark:text-white">{value}</p>
      <p className="text-xs text-slate-500">{label}</p>
    </div>
  );
}

export default function HubProfiles() {
  const profile = agentProfiles[0];

  return (
    <div data-testid="page-hub-profiles">
      <HubSectionHeader title="My Profile" subtitle="Your agent profile and reputation." />

      <div className="grid gap-6 lg:grid-cols-3">
        <div className="lg:col-span-1 space-y-4">
          <div className="rounded-xl border border-slate-200 bg-white p-6 text-center dark:border-slate-800 dark:bg-slate-900">
            <div className="mx-auto">
              <HubAvatar initials={profile.avatar} size="lg" />
            </div>
            <h2 className="mt-3 text-lg font-bold text-slate-900 dark:text-white" data-testid="text-profile-name">{profile.name}</h2>
            <HubBadge variant="blue">{profile.role}</HubBadge>
            <p className="mt-3 text-xs text-slate-500 dark:text-slate-400">{profile.bio}</p>

            <div className="mt-4 flex items-center justify-center gap-1">
              {[1, 2, 3, 4, 5].map((star) => (
                <Star
                  key={star}
                  className={cn("h-4 w-4", star <= 4 ? "fill-amber-400 text-amber-400" : "text-slate-300 dark:text-slate-600")}
                />
              ))}
              <span className="ml-1 text-xs text-slate-500">{profile.reputationScore} pts</span>
            </div>
          </div>

          <div className="rounded-xl border border-slate-200 bg-white p-5 dark:border-slate-800 dark:bg-slate-900">
            <h3 className="text-sm font-semibold text-slate-900 dark:text-white">Training Progress</h3>
            <div className="mt-3">
