export default function SocialPostsPage() {
  const { role, setRole } = useRole();
  const [searchQuery, setSearchQuery] = useState("");
  const [dateFilter, setDateFilter] = useState<DateFilter>("all");
  const [customDate, setCustomDate] = useState("");

  const {
    data,
    isLoading,
    isError,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = useFreeQuotesInfinite(12);

  // Ref for infinite scroll observer
  const loadMoreRef = useRef<HTMLDivElement>(null);

  // Setup intersection observer for infinite scroll
  useEffect(() => {
    if (!loadMoreRef.current || !hasNextPage || isFetchingNextPage) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasNextPage && !isFetchingNextPage) {
          fetchNextPage();
        }
      },
      { threshold: 0.1 }
    );

    observer.observe(loadMoreRef.current);

    return () => observer.disconnect();
  }, [hasNextPage, isFetchingNextPage, fetchNextPage]);

  // Flatten all pages into a single array of social posts
  const socialPosts = useMemo<SocialPost[]>(() => {
    if (!data?.pages) return [];

    const allQuotes: SocialPost[] = [];

    data.pages.forEach((page) => {
      page.quotes.forEach((quote) => {
        allQuotes.push({
          quote: quote as EnrichedQuote,
          clientId: quote.client_id || "",
        });
      });
    });

    return allQuotes;
  }, [data]);

  const filteredPosts = useMemo(() => {
    let result = socialPosts;

    if (searchQuery.trim()) {
      const needle = searchQuery.trim().toLowerCase();
      result = result.filter(({ quote: q }) => {
        const title = (q.title || "").toLowerCase();
        const hotel = getHotelName(q).toLowerCase();
        const airport = getDepartingAirport(q).toLowerCase();
        const subtitle = getSubtitle(q).toLowerCase();
        const tourOp = (q.main_tour_operator_name || "").toLowerCase();
        return (
          title.includes(needle) ||
          hotel.includes(needle) ||
          airport.includes(needle) ||
          subtitle.includes(needle) ||
          tourOp.includes(needle)
        );
      });
    }

    if (dateFilter === "today") {
      const today = new Date();
      result = result.filter(({ quote: q }) => isSameDay(q.date_created, today));
    } else if (dateFilter === "tomorrow") {
      const tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      result = result.filter(({ quote: q }) => isSameDay(q.date_created, tomorrow));
    } else if (dateFilter === "custom" && customDate) {
      const target = new Date(customDate + "T00:00:00");
      result = result.filter(({ quote: q }) => isSameDay(q.date_created, target));
    }

    return result;
  }, [socialPosts, searchQuery, dateFilter, customDate]);

  const dateButtons: { label: string; value: DateFilter }[] = [
    { label: "All", value: "all" },
    { label: "Today", value: "today" },
    { label: "Tomorrow", value: "tomorrow" },
    { label: "By Date", value: "custom" },
  ];

  return (
    <CommandCenterShell
      active="social-posts"
      title="Social Posts"
      subtitle="Browse and schedule social media posts from your quotes"
      role={role}
      onRoleChange={setRole}
    >
      <div className="space-y-4">
        <div className="glass ringed grain rounded-2xl p-4">
          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-black/40 dark:text-white/40" />
              <Input
                placeholder="Search by title, hotel, airport, destination..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 rounded-xl bg-black/5 dark:bg-white/5 border-black/10 dark:border-white/10"
                data-testid="input-search-social-posts"
              />
            </div>
            <div className="flex items-center gap-2">
              {dateButtons.map((btn) => (
                <Button
                  key={btn.value}
                  size="sm"
                  variant={dateFilter === btn.value ? "default" : "outline"}
                  className={`rounded-xl text-xs font-medium ${
                    dateFilter === btn.value
                      ? "bg-blue-500 hover:bg-blue-600 text-white"
                      : "border-black/10 dark:border-white/10"
                  }`}
                  onClick={() => setDateFilter(btn.value)}
                  data-testid={`button-filter-${btn.value}`}
                >
                  {btn.label}
                </Button>
              ))}
              <AnimatePresence>
                {dateFilter === "custom" && (
                  <motion.div
                    initial={{ width: 0, opacity: 0 }}
                    animate={{ width: "auto", opacity: 1 }}
                    exit={{ width: 0, opacity: 0 }}
                    className="overflow-hidden"
                  >
                    <Input
                      type="date"
                      value={customDate}
                      onChange={(e) => setCustomDate(e.target.value)}
                      className="w-40 rounded-xl text-xs bg-black/5 dark:bg-white/5 border-black/10 dark:border-white/10"
                      data-testid="input-custom-date"
                    />
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>
        </div>

        <div className="flex items-center justify-between">
          <p className="text-sm text-black/55 dark:text-white/55" data-testid="text-results-count">
            {filteredPosts.length} {filteredPosts.length === 1 ? "post" : "posts"} found
          </p>
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center py-20">
            <Spinner className="w-8 h-8" />
          </div>
        ) : isError ? (
          <div className="glass ringed grain rounded-2xl p-12 text-center">
            <p className="text-sm font-medium text-red-600 dark:text-red-400">
              Failed to load posts. Please try refreshing the page.
            </p>
          </div>
        ) : filteredPosts.length === 0 ? (
          <div className="glass ringed grain rounded-2xl p-12 text-center">
            <CalendarClock className="w-12 h-12 mx-auto text-black/20 dark:text-white/20 mb-3" />
            <p className="text-sm font-medium text-black/60 dark:text-white/60">
              No posts found
            </p>
            <p className="text-xs text-black/40 dark:text-white/40 mt-1">
              Try adjusting your search or date filters
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            <AnimatePresence mode="popLayout">
              {filteredPosts.map((post) => (
                <SocialPostCard key={post.quote.id} post={post} />
              ))}
            </AnimatePresence>
          </div>
        )}

        {/* Infinite scroll trigger */}
        {!isError && !isLoading && filteredPosts.length > 0 && (
          <div 
            ref={loadMoreRef} 
            className="flex items-center justify-center py-8"
          >
            {isFetchingNextPage && (
              <div className="flex items-center gap-2 text-sm text-black/60 dark:text-white/60">
                <Spinner className="w-5 h-5" />
                <span>Loading more posts...</span>
              </div>
            )}
            {!hasNextPage && filteredPosts.length > 0 && (
              <p className="text-sm text-black/40 dark:text-white/40">
                No more posts to load
              </p>
            )}
          </div>
        )}
      </div>
    </CommandCenterShell>
  );
}

scripts/mark-migrations.ts.content:
/**
 * This script:
 * 1. Creates accommodation_images and lodge_images tables (the only new tables not yet in DB)
 * 2. Reads the generated drizzle migration file and computes its SHA256 hash
 * 3. Inserts the hash into __drizzle_migrations so drizzle-kit migrate tracks it as applied
 */
import pg from 'pg';
import fs from 'fs';
import crypto from 'crypto';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const dbUrl = process.env.DATABASE_URL || '';
if (!dbUrl) {
  console.error('DATABASE_URL not set');
  process.exit(1);
}

const pool = new pg.Pool({
  connectionString: dbUrl,
  ssl: { rejectUnauthorized: false },
});

async function run() {
  const client = await pool.connect();
  try {
    // Step 1: Create the two new tables that don't exist yet
    console.log('Creating new tables...');

    await client.query(`
      CREATE TABLE IF NOT EXISTS accommodation_images (
        id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
        accommodation_id uuid NOT NULL,
        image_url varchar NOT NULL,
        "isPrimary" boolean DEFAULT false,
        CONSTRAINT accommodation_images_accommodation_id_image_url_unique UNIQUE(accommodation_id, image_url),
        CONSTRAINT accommodation_images_accommodation_id_fk
          FOREIGN KEY (accommodation_id) REFERENCES accomodation_list_table(id) ON DELETE CASCADE
      )
    `);
    console.log('  ✓ accommodation_images table ready');

    await client.query(`
      CREATE TABLE IF NOT EXISTS lodge_images (
        id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
        lodge_id uuid NOT NULL,
        image_url varchar NOT NULL,
        "isPrimary" boolean DEFAULT false,
        CONSTRAINT lodge_images_lodge_id_image_url_unique UNIQUE(lodge_id, image_url),
        CONSTRAINT lodge_images_lodge_id_fk
          FOREIGN KEY (lodge_id) REFERENCES lodges_table(id) ON DELETE CASCADE
      )
    `);
    console.log('  ✓ lodge_images table ready');

    // Step 2: Set up drizzle schema and __drizzle_migrations table
    // Drizzle stores migrations in the "drizzle" schema, not public
    // Clean up incorrect public.__drizzle_migrations if it exists
    await client.query(`DROP TABLE IF EXISTS public."__drizzle_migrations"`);
    await client.query(`CREATE SCHEMA IF NOT EXISTS drizzle`);
    await client.query(`
      CREATE TABLE IF NOT EXISTS drizzle."__drizzle_migrations" (
        id SERIAL PRIMARY KEY,
        hash text NOT NULL,
        created_at bigint
      )
    `);

    // Step 3: Compute SHA256 hash of the migration file (same as drizzle-orm does)
    const migrationFile = path.resolve(__dirname, '../migrations/0000_organic_gargoyle.sql');
    const content = fs.readFileSync(migrationFile, 'utf-8');
    const hash = crypto.createHash('sha256').update(content).digest('hex');
    console.log(`\nMigration hash: ${hash}`);

    // folderMillis comes from the journal's "when" field - drizzle skips migration
    // if lastDbMigration.created_at >= migration.folderMillis
    const folderMillis = 1771504056558;

    // Step 4: Insert only if not already tracked
    const { rows } = await client.query(
      `SELECT id FROM drizzle."__drizzle_migrations" WHERE hash = $1`,
      [hash]
    );

    if (rows.length === 0) {
      await client.query(
        `INSERT INTO drizzle."__drizzle_migrations" (hash, created_at) VALUES ($1, $2)`,
        [hash, folderMillis]
      );
      console.log('  ✓ Migration recorded in drizzle.__drizzle_migrations');
    } else {
      console.log('  ℹ Migration already tracked, skipping');
    }

    console.log('\n✅ Done! All migrations are now tracked. Run drizzle-kit migrate for future changes.');
  } finally {
    client.release();
    await pool.end();
  }
}

run().catch((e) => {
  console.error('Error:', e.message);
  process.exit(1);
});

